"""Independent rendered Progress page; never creates or manipulates a native window."""
from pathlib import Path
import argparse,hashlib,json,uuid
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('manifest',type=Path);p.add_argument('--peer-only',action='store_true');a=p.parse_args();m=json.loads(a.manifest.read_text());stage=json.loads((a.manifest.parent/'windows-stage.json').read_text());assert m['owner']=='root' and m['component']=='progresspage' and m['runtime']=='win-x64' and stage['selfContained'];nonce=uuid.uuid4().hex;out=a.manifest.parent/'windows-headless'/nonce;out.mkdir(parents=True)
cases=(r/'docs/replica/source/root-progresspage-cases.json').read_bytes();served='root-progresspage-'+nonce+'-headless-cases.json';(r/'artifacts/replica/windows-download'/served).write_bytes(cases);sha=hashlib.sha256(cases).hexdigest().upper();base="$app=Join-Path (Join-Path $env:TEMP "+q(stage['guestFolder'])+") 'app';$out=Join-Path $app "+q('headless-'+nonce)+";"
code=base+"$ProgressPreference='SilentlyContinue';New-Item -ItemType Directory $out -Force|Out-Null;$cases=Join-Path $out 'cases.json';Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+served)+" -OutFile $cases;if((Get-FileHash $cases -Algorithm SHA256).Hash-ne "+q(sha)+"){throw 'Cases hash mismatch'};if((Get-FileHash ($app+'\\ReplicaProbe.dll') -Algorithm SHA256).Hash-ne "+q(m['binarySha256'].upper())+"){throw 'Binary hash mismatch'};$env:DBMV_HEADLESS='1';$env:DBMV_HEADLESS_SCALE='2';& ($app+'\\ReplicaProbe.exe') '--progresspage' $cases $out "+("'--peer-only' " if a.peer_only else "")+";if($LASTEXITCODE-ne0){throw 'Rendered headless failed'};"
command=r/'artifacts/replica/windows-download'/('root-progress-headless-command-'+nonce+'.txt');command.write_text(code);commandsha=hashlib.sha256(command.read_bytes()).hexdigest().upper();loader="$f=Join-Path $env:TEMP "+q(command.name)+";Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+command.name)+" -OutFile $f;if((Get-FileHash $f -Algorithm SHA256).Hash-ne "+q(commandsha)+"){throw 'Own command hash mismatch'};&([scriptblock]::Create([IO.File]::ReadAllText($f)));";
(out/'command.json').write_text(json.dumps({'script':str(command),'sha256':commandsha,'scope':'independent rendered headless; no native input'},indent=2));print(ps(loader,timeout=30))
for name in (['progresspage-native.json','progresspage-peer.json'] if a.peer_only else ['progresspage-native.json','progresspage-lifecycle.json']):(out/name).write_text(ps(base+"Get-Content -Raw (Join-Path $out "+q(name)+")",retry_read=True)+'\n')
v=json.loads((out/'progresspage-native.json').read_text());assert len(v['rows'])==(4 if a.peer_only else 80)
(out/'environment.json').write_text(json.dumps({'phase':'HEADLESS_RECORDED','headless':True,'rendering':'realSkia','dpr':v['dpr'],'manifest':str(a.manifest.resolve()),'stage':stage,'binarySha256':m['binarySha256'],'casesSha256':sha},indent=2)+'\n');print(out)
